document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".navbar-toggler"),n=e.querySelector(".icon-1"),t=e.querySelector(".icon-2"),o=document.querySelector("#navbarToggler");function d(){var e=document.querySelector(".header");if(e){var n=e.getBoundingClientRect().height;document.documentElement.style.setProperty("--header-height",n+"px")}}o.addEventListener("shown.bs.collapse",function(){n.style.display="none",t.style.display="inline"}),o.addEventListener("hidden.bs.collapse",function(){n.style.display="inline",t.style.display="none"}),window.addEventListener("DOMContentLoaded",d),window.addEventListener("resize",d)});